local CeremonialSwordMaker = {}
local PRODUCTS = {
    simple_steel_ceremonial_sword = { name = "Preprost jekleni slovesni meč", steelCost = 2, ironCost = 1, woodCost = 1, time = 5, cost = 200, prestige = 5, happiness = 2, description = "Preprost jekleni slovesni meč za parade." },
    silver_hilt_ceremonial_sword = { name = "Srebrnorokavni slovesni meč", steelCost = 2, silverCost = 2, ironCost = 1, woodCost = 1, time = 8, cost = 480, prestige = 12, happiness = 3, description = "Srebrnorokavni slovesni meč za trgovce." },
    gold_trimmed_ceremonial_sword = { name = "Zlatookrasni slovesni meč", steelCost = 2, goldCost = 2, silverCost = 1, ironCost = 1, woodCost = 1, time = 12, cost = 1100, prestige = 22, happiness = 4, description = "Zlatookrasni slovesni meč za plemiče." },
    jewel_pommel_ceremonial_sword = { name = "Draguljnogrbi slovesni meč", steelCost = 2, goldCost = 2, silverCost = 1, ironCost = 1, woodCost = 1, jewelCost = 1, time = 16, cost = 2500, prestige = 35, happiness = 6, description = "Slovesni meč z draguljnim grbičem za visoke plemiče." },
    pearl_set_ceremonial_sword = { name = "Bisernavi slovesni meč", steelCost = 2, goldCost = 3, silverCost = 1, ironCost = 1, woodCost = 1, jewelCost = 1, pearlCost = 1, time = 20, cost = 5200, prestige = 50, happiness = 8, description = "Slovesni meč z biseri za visoko plemstvo." },
    royal_grand_ceremonial_sword = { name = "Kraljevski veliki slovesni meč", steelCost = 3, goldCost = 4, silverCost = 2, ironCost = 1, woodCost = 1, jewelCost = 2, pearlCost = 2, time = 27, cost = 11000, prestige = 75, happiness = 13, description = "Veliki kraljevski slovesni meč z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    ceremonial_workshop = { name = "Slovesna delavnica", cost = { gold = 320, wood = 120, stone = 140, steel = 6, iron = 4 }, upkeep = 7, qualityBonus = 5 },
    armorer_loft = { name = "Okleparska podstrešje", cost = { gold = 1100, wood = 280, stone = 280, silver = 6, gold = 4 }, upkeep = 26, qualityBonus = 18 },
    master_ceremonial_atelier = { name = "Mojstrski slovesni atelje", cost = { gold = 2900, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 68, qualityBonus = 30 },
    royal_armory_palace = { name = "Kraljevska orožarnaica palača", cost = { gold = 12500, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 250, qualityBonus = 55, prestigeBonus = 50 },
}
CeremonialSwordMaker.steelStock = 14; CeremonialSwordMaker.ironStock = 12; CeremonialSwordMaker.woodStock = 10; CeremonialSwordMaker.silverStock = 8; CeremonialSwordMaker.goldStock = 6; CeremonialSwordMaker.jewelStock = 4; CeremonialSwordMaker.pearlStock = 4
CeremonialSwordMaker.productStock = {}; CeremonialSwordMaker.buildings = {}; CeremonialSwordMaker.maker = nil; CeremonialSwordMaker.activeMaking = {}; CeremonialSwordMaker.totalProducts = 0; CeremonialSwordMaker.dayTimer = 0
function CeremonialSwordMaker.init() CeremonialSwordMaker.steelStock=14; CeremonialSwordMaker.ironStock=12; CeremonialSwordMaker.woodStock=10; CeremonialSwordMaker.silverStock=8; CeremonialSwordMaker.goldStock=6; CeremonialSwordMaker.jewelStock=4; CeremonialSwordMaker.pearlStock=4; CeremonialSwordMaker.productStock={}; CeremonialSwordMaker.buildings={}; CeremonialSwordMaker.maker=nil; CeremonialSwordMaker.activeMaking={}; CeremonialSwordMaker.totalProducts=0; CeremonialSwordMaker.dayTimer=0; print("[CeremonialSwordMaker] Royal Ceremonial Sword Maker System initialized (6 products, 4 buildings)") end
function CeremonialSwordMaker.hireMaker(n,s) s=s or math.random(55,90); local c=600+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CeremonialSwordMaker.maker={name=n or ("Slovesni mečar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Slovesni mečar najet: %s (spretnost: %d)",CeremonialSwordMaker.maker.name,s),"success") end; return true end
function CeremonialSwordMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CeremonialSwordMaker.build(id) local ok,e=CeremonialSwordMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CeremonialSwordMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CeremonialSwordMaker.getQualityBonus() local b=0; for _,bd in ipairs(CeremonialSwordMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CeremonialSwordMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.steelCost and CeremonialSwordMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.ironCost and CeremonialSwordMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.woodCost and CeremonialSwordMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.silverCost and CeremonialSwordMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CeremonialSwordMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CeremonialSwordMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CeremonialSwordMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CeremonialSwordMaker.buildings==0 then return false,"Potrebna slovesna delavnica" end; if not CeremonialSwordMaker.maker then return false,"Potreben slovesni mečar" end; return true end
function CeremonialSwordMaker.make(pt,qty) qty=qty or 1; local ok,e=CeremonialSwordMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.steelCost then CeremonialSwordMaker.steelStock=CeremonialSwordMaker.steelStock-d.steelCost*qty end; if d.ironCost then CeremonialSwordMaker.ironStock=CeremonialSwordMaker.ironStock-d.ironCost*qty end; if d.woodCost then CeremonialSwordMaker.woodStock=CeremonialSwordMaker.woodStock-d.woodCost*qty end; if d.silverCost then CeremonialSwordMaker.silverStock=CeremonialSwordMaker.silverStock-d.silverCost*qty end; if d.goldCost then CeremonialSwordMaker.goldStock=CeremonialSwordMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CeremonialSwordMaker.jewelStock=CeremonialSwordMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CeremonialSwordMaker.pearlStock=CeremonialSwordMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CeremonialSwordMaker.maker then t=math.max(1,t-math.floor(CeremonialSwordMaker.maker.skill/12)) end; table.insert(CeremonialSwordMaker.activeMaking,{id="ceremonialsword_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kovanje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CeremonialSwordMaker.completeMaking(m) local q=1.0+(CeremonialSwordMaker.getQualityBonus()/100); if CeremonialSwordMaker.maker then q=q+(CeremonialSwordMaker.maker.skill/140) end; q=math.min(2.5,q); CeremonialSwordMaker.productStock[m.productType]=(CeremonialSwordMaker.productStock[m.productType] or 0)+m.quantity; CeremonialSwordMaker.totalProducts=CeremonialSwordMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CeremonialSwordMaker.maker then CeremonialSwordMaker.maker.itemsMade=CeremonialSwordMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CeremonialSwordMaker.maker.skill=math.min(100,CeremonialSwordMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Slovesni meč izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"ceremonialsword.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CeremonialSwordMaker.update(dt) if not _G.state then return end; CeremonialSwordMaker.dayTimer=CeremonialSwordMaker.dayTimer+dt; if CeremonialSwordMaker.dayTimer>=30 then CeremonialSwordMaker.dayTimer=0; for i=#CeremonialSwordMaker.activeMaking,1,-1 do local m=CeremonialSwordMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CeremonialSwordMaker.completeMaking(m); table.remove(CeremonialSwordMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CeremonialSwordMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CeremonialSwordMaker.maker then tu=tu+16 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CeremonialSwordMaker.getStats() return {steelStock=CeremonialSwordMaker.steelStock,ironStock=CeremonialSwordMaker.ironStock,woodStock=CeremonialSwordMaker.woodStock,silverStock=CeremonialSwordMaker.silverStock,goldStock=CeremonialSwordMaker.goldStock,jewelStock=CeremonialSwordMaker.jewelStock,pearlStock=CeremonialSwordMaker.pearlStock,productStock=CeremonialSwordMaker.productStock,numBuildings=#CeremonialSwordMaker.buildings,hasMaker=CeremonialSwordMaker.maker~=nil,makerName=CeremonialSwordMaker.maker and CeremonialSwordMaker.maker.name or "—",makerSkill=CeremonialSwordMaker.maker and CeremonialSwordMaker.maker.skill or 0,activeMaking=#CeremonialSwordMaker.activeMaking,totalProducts=CeremonialSwordMaker.totalProducts} end
return CeremonialSwordMaker
